/* ==UserStyle==
@name           VK — Red Bull Rain (весь сайт)
@namespace      userstyles.world
@version        4.0.0
@description    Тёмный дождливый фон с гонщиком Red Bull для всего сайта VK
@license        CC0
==/UserStyle== */
@-moz-document domain("vk.ru"), domain("vk.com") {
/* ============ 1. ПЕРЕМЕННЫЕ ============ */
  :root {
    /* Фото из Google Drive через lh3.googleusercontent.com (проверено: загружается) */
    --rb-photo: url("https://lh3.googleusercontent.com/d/1rJRVQdiEttOPkwP91d_LSFWmw280jfJp");

    --rb-navy: #0a0e18;
    --rb-red: #dc0000;
    --rb-yellow: #ffc906;
    --rb-glass: rgba(10, 14, 24, 0.55);
    --rb-glass-strong: rgba(10, 14, 24, 0.78);
    --rb-hover: rgba(255, 255, 255, 0.05);
    --rb-text: #f2f4f8;
    --rb-muted: #9aa3b5;
  }

  /* ============ 2. ФОН ВСЕГО САЙТА ============
     Фото ставим на html и body: это работает на любой странице VK,
     включая музыку и мессенджер. */
  html,
  body {
    background-color: #0a0e18 !important;
    background:
      linear-gradient(180deg, rgba(10, 14, 24, 0.45) 0%, rgba(10, 14, 24, 0.85) 100%),
      var(--rb-photo) center / cover no-repeat fixed !important;
  }

  /* Прозрачные контейнеры, чтобы фото было видно */
  .vkui__root,
  #page_layout,
  #page_body,
  .page_wrap,
  .LayoutWrapper__body--4KrQR {
    background: transparent !important;
  }

  /* ============ 3. ТЁМНАЯ ТЕМА VK (переменные vkui) ============ */
  .vkui--vkBase--dark {
    --vkui--color_background: transparent !important;
    --vkui--color_background_content: rgba(14, 18, 30, 0.6) !important;
    --vkui--color_background_secondary: rgba(255, 255, 255, 0.05) !important;
    --vkui--color_text_primary: var(--rb-text) !important;
  }

  /* ============ 4. ВЕРХНЯЯ ПАНЕЛЬ И ЛЕВОЕ МЕНЮ (стекло) ============ */
  /* Шапка без своего цвета: показывает тот же фон, что и вся страница */
  .TopNavigationWrapper__outer--mr0BU,
  .TopNavigationWrapper__inner--8vD9H,
  .TopNavigation__search--xWjWS,
  .TopNavigation__player--YMED3 {
    background: transparent !important;
    box-shadow: none !important;
  }
  .LeftMenu__leftMenu {
    background: var(--rb-glass) !important;
    -webkit-backdrop-filter: blur(16px) saturate(140%);
    backdrop-filter: blur(16px) saturate(140%);
  }

  /* ============ 5. МЕССЕНДЖЕР: СПИСОК ДИАЛОГОВ (стекло) ============ */
  .MEApp {
    background: transparent !important;
  }
  .ConvoList,
  .ConvoList__header,
  .ConvoList__top,
  .ConvoList__searchBar {
    background: var(--rb-glass) !important;
    -webkit-backdrop-filter: blur(16px) saturate(140%);
    backdrop-filter: blur(16px) saturate(140%);
  }
  .ConvoList__search {
    background: rgba(255, 255, 255, 0.06) !important;
    border-radius: 12px !important;
  }
  .ConvoList__search .vkuiSearch__nativeInput {
    color: var(--rb-text) !important;
  }

  /* Диалоги */
  .ConvoListItem--click {
    border-radius: 12px;
    transition: background 0.2s ease;
  }
  .ConvoListItem--click:hover {
    background: var(--rb-hover) !important;
  }
  .ConvoListItem--muted {
    opacity: 0.7;
  }
  .ConvoTitle__title,
  .ConvoTitle__author {
    color: var(--rb-text) !important;
    font-weight: 600;
  }
  .ConvoListItem__text,
  .MessagePreview,
  .ConvoListItem__date {
    color: var(--rb-muted) !important;
  }
  .MessagePreview__attach,
  .ConvoListItem__outStatusIcon {
    color: var(--rb-yellow) !important;
  }
  .MEAvatar__imgWrapper {
    border-radius: 50%;
    box-shadow: 0 0 0 2px rgba(220, 0, 0, 0.45);
  }

  /* ============ 6. СКРОЛЛБАР И ВЫДЕЛЕНИЕ ============ */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(220, 0, 0, 0.45);
    border-radius: 8px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--rb-red);
  }
  ::selection {
    background: rgba(255, 201, 6, 0.45);
    color: #000;
  }
}
